item.command:
/bin/bash -lc "python - <<'PY'
import urllib.request,json,pathlib
p=pathlib.Path('intake')
urls={'megadock_tag':'https://api.github.com/repos/akiyamalab/MEGADOCK/git/ref/tags/4.1.4','megadock_readme':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/README.md','megadock_build':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/doc/BUILD.md','megadock_usage':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/doc/README.md','megadock_license':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/LICENSE','megadock_makefile':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/Makefile','pinder_license':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/LICENSE','pinder_readme':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/README.md'}
from concurrent.futures import ThreadPoolExecutor
def get(kv):
 k,u=kv
 try:
  b=urllib.request.urlopen(u,timeout=30).read(); (p/(k+'.txt')).write_bytes(b);return k,b.decode()[:18000]
 except Exception as e:return k,str(e)
for k,v in ThreadPoolExecutor(8).map(get,urls.items()):print(k+'\\n'+v)
PY"

